import { BASE_ADVANCED_ACTION_IDS, BASE_ARYTHEA_SKILLS, BASE_ARTIFACT_IDS, BASE_CONTENT_COUNTS, BASE_GOLDYX_SKILLS, BASE_NOROWAS_SKILLS, BASE_RUINS_TOKENS, BASE_SPELL_IDS, BASE_TOVAK_SKILLS, calculateScore, CHARACTER_PROFILES, CITY_GARRISONS, CONTENT_COUNTS, createGame, createMultiplayerGame, ENEMIES, gameViewForPlayer, legalExplorations, legalMoves, legalTunnelMoves, reduceGame, SCENARIO_TILE_COUNTS, TERRAIN_COST, SITES, TACTICS, TOVAK_SKILLS, unitArmor, unitKey, UNITS } from './gameEngine';
import { MAP_TILES, STARTING_TILES } from './gameContent';

const act = (state, type, extra={}) => reduceGame(state,{type,...extra});
const hexDistance = (a,b) => (Math.abs(a.q-b.q)+Math.abs(a.r-b.r)+Math.abs((-a.q-a.r)-(-b.q-b.r)))/2;
const placeNextTo=(player,hex)=>Object.assign(player,{q:hex.q-1,r:hex.r});
const explorationFromFrontier=(state,range=1)=>{for(const origin of state.map.filter(hex=>hex.revealed!==false)){Object.assign(state.player,{q:origin.q,r:origin.r});const option=legalExplorations(state).find(item=>hexDistance(state.player,item)===range);if(option)return option;}return undefined;};
const forceExplore=(state,tileId)=>{state.tileDeck=[tileId];const option=explorationFromFrontier(state);if(!option)throw new Error(`No legal frontier for ${tileId}`);state.points.move=2;return {state:reduceGame(state,{type:'EXPLORE',q:option.q,r:option.r,playerId:state.activePlayerId}),option};};
const provocationRoute=(state,rampager)=>{const spaces=state.map.filter(hex=>hex.revealed!==false&&!hex.enemy&&Number.isFinite(TERRAIN_COST[state.time][hex.terrain])&&hexDistance(hex,rampager)===1);for(const origin of spaces){const destination=spaces.find(hex=>hex!==origin&&hexDistance(origin,hex)===1);if(destination)return {origin,destination};}return {};};
const pickTactics = (state,selections={p1:'early-bird',p2:'rethink'}) => {let next=state;while(next.phase==='tactic'&&next.tacticPickerId){const playerId=next.tacticPickerId;next=reduceGame(next,{type:'SELECT_TACTIC',id:selections[playerId],playerId});}return next;};
const resolveLevelUps = state => {let next=state;while(next.phase==='level-up'){const skill=next.skillChoices[0]||next.commonSkills[0];if(!skill)break;const playerId=next.levelUpContext?.playerId;next=reduceGame(next,{type:'SELECT_SKILL',id:skill.id,advancedId:next.offer.advanced[0]?.id,...(playerId?{playerId}:{})});}return next;};
const cardToHand = (state,id) => {
  const source=state.player.hand.find(c=>c.id===id)?state.player.hand:state.player.deck;
  const i=source.findIndex(c=>c.id===id); const card=source.splice(i,1)[0];
  if(!state.player.hand.includes(card))state.player.hand.push(card); return card;
};
const catalogCard=(kind,id)=>{const catalog=createGame(8675309),piles=kind==='advanced'?[catalog.offer.advanced,catalog.offer.monastery,catalog.decks.advanced]:kind==='spell'?[catalog.offer.spells,catalog.decks.spells]:[catalog.decks.artifacts];return piles.flat().find(card=>card.id===id);};
const advancedToHand=(state,id)=>{const piles=[state.offer.advanced,state.offer.monastery||[],state.decks.advanced],source=piles.find(pile=>pile.some(card=>card.id===id));let card;if(source){const index=source.findIndex(item=>item.id===id);card=source.splice(index,1)[0];}else card=catalogCard('advanced',id);if(!card)throw new Error(`Missing Advanced Action ${id}`);card={...card,uid:card.uid||`test-${id}-${state.turn}-${state.player.hand.length}`};state.player.hand.push(card);return card;};
const spellToHand=(state,id)=>{const piles=[state.offer.spells,state.decks.spells],source=piles.find(pile=>pile.some(card=>card.id===id));let card;if(source){const index=source.findIndex(item=>item.id===id);card=source.splice(index,1)[0];}else card=catalogCard('spell',id);if(!card)throw new Error(`Missing Spell ${id}`);card={...card,uid:card.uid||`test-${id}-${state.turn}`};state.player.hand.push(card);return card;};
const artifactToHand=(state,id)=>{const source=state.decks.artifacts,index=source.findIndex(item=>item.id===id);let card=index>=0?source.splice(index,1)[0]:catalogCard('artifact',id);if(!card)throw new Error(`Missing Artifact ${id}`);card={...card,uid:card.uid||`test-${id}-${state.turn}`};state.player.hand.push(card);return card;};
const unitForTest=(id,uid=`test-${id}`)=>({...JSON.parse(JSON.stringify(UNITS.find(unit=>unit.id===id))),uid,spent:false,wounded:false,woundCount:0});
const lobby=scenario=>({id:'SCENARIO',scenario,players:[{id:'p1',name:'One',character:'tovak'},{id:'p2',name:'Two',character:'arythea'}]});

test('content decks expose every implemented card',()=>{expect(CONTENT_COUNTS).toEqual({advancedActions:31,spells:24,artifacts:21,units:40,characters:7});});
test('base-game card manifests match the original component inventory',()=>{expect(BASE_CONTENT_COUNTS).toEqual({advancedActions:28,spells:20,artifacts:16,units:40,characters:4});expect(new Set(BASE_ADVANCED_ACTION_IDS).size).toBe(28);expect(new Set(BASE_SPELL_IDS).size).toBe(20);expect(new Set(BASE_ARTIFACT_IDS).size).toBe(16);});
