  foresters:[2,1,5,4,'village','', 'block:3,trailcraft:2'],
  'utem-crossbowmen':[2,2,6,4,'keep,village','', 'attack:3,block:3,ranged:2'],
  'utem-guardsmen':[2,2,5,5,'keep,village','', 'attack:2,block:4'],
  'utem-swordsmen':[2,2,6,4,'keep','', 'attack:3,block:3,fierce-attack:6,fierce-block:6'],
  'guardian-golems':[2,2,7,3,'keep,mage-tower','physical', 'attack:2,block:2,fire-block:4,ice-block:4'],
  illusionists:[2,2,7,2,'mage-tower,monastery','physical', 'influence:4,veil:1,white-crystal:1'],
