  'northern-monks':[1,2,7,4,'monastery','', 'attack:3,block:3,ice-attack:4,ice-block:4'],
  'savage-monks':[1,2,7,4,'monastery','', 'attack:3,block:3,siege:4'],
  'fire-golems':[2,3,8,4,'keep,mage-tower','fire', 'attack:3,block:3,fire-ranged:4'],
  'ice-golems':[2,3,8,4,'keep,mage-tower','ice', 'greater-ice-attack:6,ice-attack:3,ice-block:3'],
  'fire-mages':[2,3,9,3,'mage-tower,monastery','fire', 'fire-attack:6,fire-block:6,fire-ranged:3,red-mana-crystal:1'],
  'ice-mages':[2,3,9,4,'mage-tower,monastery','ice', 'blue-mana-crystal:1,ice-attack:4,ice-block:4,ice-siege:4'],
  'amotep-gunners':[2,3,8,6,'city,keep','', 'attack:5,block:5,fire-ranged:6'],
