  test('Amulet of the Sun applies daytime visibility, forest cost, and gold mana rules for one Night turn',()=>{let s=createGame(),amulet=artifactToHand(s,'amulet-of-the-sun'),keep=s.map.find(hex=>hex.site==='keep'&&hex.enemy),keepKey=`${keep.q}:${keep.r}`,origin={q:keep.q-1,r:keep.r},forest=s.map.find(hex=>hex.revealed!==false&&hex.q!==keep.q&&hexDistance(hex,origin)===1),ruinKeys=s.map.filter(hex=>hex.site==='ruins'&&hex.ruinsToken).map(hex=>`${hex.q}:${hex.r}`);s.time='night';Object.assign(s.player,origin);Object.assign(forest,{terrain:'forest',site:null,enemy:null,enemies:[],revealed:true});keep.enemyFaceDown=true;s.map.filter(hex=>ruinKeys.includes(`${hex.q}:${hex.r}`)).forEach(hex=>{hex.ruinsToken.faceDown=true;});s.points.move=99;expect(legalMoves(s).find(hex=>hex.q===forest.q&&hex.r===forest.r).cost).toBe(5);s.player.hand=[amulet];s=act(s,'PLAY_CARD',{uid:amulet.uid,mode:'basic'});expect(s.error).toBeNull();expect(s.mana).toEqual(['gold']);expect(s.bonuses.goldAsBasic).toBe(true);expect(legalMoves(s).find(hex=>hex.q===forest.q&&hex.r===forest.r).cost).toBe(3);expect(s.map.find(hex=>`${hex.q}:${hex.r}`===keepKey).enemyFaceDown).toBe(false);expect(s.map.filter(hex=>ruinKeys.includes(`${hex.q}:${hex.r}`)).every(hex=>!hex.ruinsToken.faceDown)).toBe(true);expect(s.undoCheckpoint).toBeNull();});
  test('Amulet of the Sun gold token and Source die power basic colors during Night combat',()=>{let s=createGame(),amulet=artifactToHand(s,'amulet-of-the-sun'),strike={id:'sun-strike',uid:'sun-strike',name:'Sun Strike',color:'red',type:'basic',basic:{attack:2},strong:{attack:4}};s.time='night';s.phase='combat-attack';s.combat={enemy:{id:'sun-target',uid:'sun-target',name:'Target',armor:20,attack:0,traits:[]},enemies:[],defeatedIds:[],blockedIds:[]};s.player.hand=[amulet,strike];s.source[0].color='gold';s=act(s,'PLAY_CARD',{uid:amulet.uid,mode:'basic'});s=act(s,'TAKE_SOURCE',{id:s.source[0].id});expect(s.error).toBeNull();expect(s.mana).toEqual(['gold','gold']);s=act(s,'PLAY_CARD',{uid:strike.uid,mode:'strong'});expect(s.error).toBeNull();expect(s.points.attack).toBe(4);expect(s.mana).toEqual(['gold']);});
