  test('Soul Harvester basic gains one legal crystal from a group defeated by its attack',()=>{let s=createGame(),harvester=artifactToHand(s,'soul-harvester'),guard={id:'guard',uid:'harvest-guard',name:'Guard',armor:1,attack:0,fame:1,traits:[]},golem={id:'golem',uid:'harvest-golem',name:'Golem',armor:1,attack:0,fame:1,traits:['physical-resistant']};s.phase='combat-attack';s.combat={q:null,r:null,kind:'provoked',enemy:{name:'Group',fame:2,members:[guard,golem]},enemies:[guard,golem],enemySources:{},defeatedIds:[],blockedIds:[]};s.player.hand=[harvester];s.points.attack=1;s=act(s,'PLAY_CARD',{uid:harvester.uid,mode:'basic'});s=act(s,'RESOLVE_ATTACK',{targetIds:[guard.uid,golem.uid]});expect(s.pendingSoulHarvest.rewards).toHaveLength(1);expect(s.pendingSoulHarvest.rewards[0].candidates).toEqual(expect.arrayContaining([expect.objectContaining({id:guard.uid,colors:['white']}),expect.objectContaining({id:golem.uid,colors:['white','green']})]));s=act(s,'RESOLVE_SOUL_HARVEST',{enemyId:golem.uid,color:'green'});expect(s.error).toBeNull();expect(s.pendingSoulHarvest).toBeNull();expect(s.player.crystals.green).toBe(1);});
  test('Soul Harvester strong rewards earlier and later phase defeats but excludes summoned enemies',()=>{let s=createGame(),harvester=artifactToHand(s,'soul-harvester'),fire={id:'fire',uid:'harvest-fire',name:'Fire Resistant',armor:1,attack:0,fame:1,traits:['fire-resistant']},ice={id:'ice',uid:'harvest-ice',name:'Ice Resistant',armor:1,attack:0,fame:1,traits:['ice-resistant']},summoned={id:'summoned',uid:'harvest-summoned',summonerId:'summoner',name:'Summoned',armor:1,attack:0,fame:0,traits:['physical-resistant']};s.phase='combat-attack';s.combat={q:null,r:null,kind:'provoked',enemy:{name:'Group',fame:2,members:[fire,ice,summoned]},enemies:[fire,ice,summoned],enemySources:{},defeatedIds:[],blockedIds:[]};s.player.hand=[harvester];s.points.attack=1;s=act(s,'RESOLVE_ATTACK',{targetIds:[fire.uid]});s=act(s,'PLAY_CARD',{uid:harvester.uid,mode:'strong'});expect(s.pendingSoulHarvest.rewards[0].candidates[0]).toMatchObject({id:fire.uid,colors:['white','red']});s=act(s,'RESOLVE_SOUL_HARVEST',{enemyId:fire.uid,color:'red'});s=act(s,'RESOLVE_ATTACK',{targetIds:[ice.uid,summoned.uid]});expect(s.pendingSoulHarvest.rewards).toHaveLength(1);expect(s.pendingSoulHarvest.rewards[0].candidates[0]).toMatchObject({id:ice.uid,colors:['white','blue']});s=act(s,'RESOLVE_SOUL_HARVEST',{enemyId:ice.uid,color:'blue'});expect(s.error).toBeNull();expect(s.pendingSoulHarvest).toBeNull();expect(s.player.crystals).toMatchObject({red:1,blue:1,green:0,white:0});expect(s.player.removed.map(card=>card.id)).toContain('soul-harvester');});
  test('Druidic Staff basic side converts a discarded card color into its matching aspect',()=>{const results=['white','blue','red','green'].map(color=>{let s=createGame(),staff=artifactToHand(s,'druidic-staff'),payment={id:`druid-${color}`,uid:`druid-${color}`,name:`${color} Offering`,color,type:'basic',basic:{move:1},strong:{move:2}},unit={...unitForTest('peasants',`druid-unit-${color}`),spent:true};s.player.hand=[staff,payment];s.player.units=[unit];const choices={discardUid:payment.uid,...(color==='blue'?{crystalColors:['red','green']}:{}),...(color==='red'?{unitId:unit.uid}:{})};s=act(s,'PLAY_CARD',{uid:staff.uid,mode:'basic',...choices});return {error:s.error,discarded:s.player.discard.map(card=>card.uid),move:s.points.move,rule:s.bonuses.movementRules.at(-1),crystals:s.player.crystals,spent:s.player.units[0].spent,heal:s.points.heal};});expect(results).toMatchObject([{error:null,discarded:['druid-white'],move:2,rule:{allTraversable:{replace:1}}},{error:null,discarded:['druid-blue'],crystals:{red:1,green:1}},{error:null,discarded:['druid-red'],spent:false},{error:null,discarded:['druid-green'],heal:3}]);});
  test('Druidic Staff ultimate combines two chosen aspects and destroys the staff',()=>{let s=createGame(),staff=artifactToHand(s,'druidic-staff'),unit={...unitForTest('peasants','druid-ready'),spent:true};s.player.hand=[staff];s.player.units=[unit];s=act(s,'PLAY_CARD',{uid:staff.uid,mode:'strong',druidicPair:['blue','red'],crystalColors:['white','white'],unitId:unit.uid});expect(s.error).toBeNull();expect(s.player.crystals.white).toBe(2);expect(s.player.units[0].spent).toBe(false);expect(s.player.removed.map(card=>card.id)).toContain('druidic-staff');});
  test('Banner of Fear spends its attached Unit to cancel one attack and gain Fame',()=>{let s=createGame(),banner=artifactToHand(s,'banner-of-fear'),unit={...unitForTest('peasants','fear-unit'),spent:false},enemy={id:'fear-enemy',uid:'fear-enemy',name:'Fear Enemy',armor:5,attack:4,traits:[]};s.player.hand=[banner];s.player.units=[unit];s=act(s,'ASSIGN_BANNER',{uid:banner.uid,unitId:unit.uid});s.phase='combat-block';s.combat={enemy:{...enemy},enemies:[enemy],blockEnemies:[enemy],defeatedIds:[],blockedIds:[]};s=act(s,'USE_BANNER',{unitId:unit.uid,targetId:enemy.uid});expect(s.error).toBeNull();expect(s.player.fame).toBe(1);expect(s.player.units[0]).toMatchObject({spent:true,banner:{used:true}});expect(s.combat.blockedIds).toContain(enemy.uid);});

  test('Banner of Protection passively adds Armor plus Fire and Ice resistance to its Unit',()=>{let s=createGame(),banner=artifactToHand(s,'banner-of-protection'),unit={...unitForTest('peasants','protected-unit'),armor:2,resistances:[]},enemy={id:'fire-test',uid:'fire-test',name:'Fire Test',armor:3,attack:3,traits:['fire']};s.player.hand=[banner];s.player.units=[unit];s=act(s,'ASSIGN_BANNER',{uid:banner.uid,unitId:unit.uid});s.phase='combat-damage';s.combat={enemy,enemies:[enemy],damageQueue:[enemy],damageUnits:[],damageAssignedUnitIds:[],defeatedIds:[],blockedIds:[],woundsTaken:0};s=act(s,'ASSIGN_DAMAGE_UNIT',{id:unit.uid});s=act(s,'RESOLVE_DAMAGE');expect(s.error).toBeNull();expect(s.player.units[0]).toMatchObject({wounded:false,banner:{id:'banner-of-protection'}});expect(s.player.wounds).toBe(0);expect(s.combat.damageAssignedUnitIds).toContain(unit.uid);});

  test('Banner of Protection may be destroyed at turn end to remove only Wounds received that turn',()=>{let s=createGame(),banner=artifactToHand(s,'banner-of-protection'),pain={id:'pain',uid:'pain',name:'Pain',color:'red',type:'advanced',basic:{move:1,woundCost:1},strong:{move:2}};s.player.hand=[banner,pain];s.player.discard=[{id:'wound',uid:'old-wound',name:'Wound'}];s.player.wounds=1;s=act(s,'PLAY_CARD',{uid:banner.uid,mode:'strong'});s=act(s,'PLAY_CARD',{uid:pain.uid,mode:'basic'});const received=s.player.hand.find(card=>card.id==='wound');s.player.hand=s.player.hand.filter(card=>card.uid!==received.uid);s.player.discard.push(received);s=act(s,'END_TURN');expect(s.pendingBannerProtection).toMatchObject({woundUids:[received.uid],bannerUid:banner.uid});expect(s.turn).toBe(1);expect(s.player.removed).toHaveLength(0);s=act(s,'RESOLVE_BANNER_PROTECTION',{removeWounds:true});expect(s.error).toBeNull();expect(s.pendingBannerProtection).toBeNull();expect(s.turn).toBe(2);expect(s.player.wounds).toBe(1);expect(s.player.discard.map(card=>card.uid)).toContain('old-wound');expect(s.player.discard.map(card=>card.uid)).not.toContain(received.uid);expect(s.player.removed.map(card=>card.id)).toContain('banner-of-protection');});

  test('declining Banner of Protection keeps the Wounds and discards the undestroyed Artifact',()=>{let s=createGame(),banner=artifactToHand(s,'banner-of-protection'),pain={id:'pain',uid:'pain-decline',name:'Pain',color:'red',type:'advanced',basic:{move:1,woundCost:1},strong:{move:2}};s.player.hand=[banner,pain];s=act(s,'PLAY_CARD',{uid:banner.uid,mode:'strong'});s=act(s,'PLAY_CARD',{uid:pain.uid,mode:'basic'});s=act(s,'END_TURN');expect(s.pendingBannerProtection.woundUids).toHaveLength(1);s=act(s,'RESOLVE_BANNER_PROTECTION',{removeWounds:false});expect(s.player.wounds).toBe(1);expect(s.player.removed).toHaveLength(0);expect(s.player.discard.map(card=>card.id)).toContain('banner-of-protection');expect(s.player.woundsReceivedThisTurn).toEqual([]);});
  test('Bow of Starsdawn discards any chosen non-Wounds for one combined Ranged Attack and bonus Fame',()=>{let s=createGame(),bow=artifactToHand(s,'bow-of-stars'),fuel=[{id:'fuel-a',uid:'fuel-a',name:'Fuel A',color:'red',basic:{move:1},strong:{move:2}},{id:'fuel-b',uid:'fuel-b',name:'Fuel B',color:'blue',basic:{move:1},strong:{move:2}}],enemy={id:'bow-target',uid:'bow-target',name:'Bow Target',armor:4,attack:1,fame:2,traits:[]};s.player.hand=[bow,...fuel,{id:'wound',uid:'bow-wound',name:'Wound'}];s.phase='combat-ranged';s.combat={q:0,r:0,kind:'provoked',enemy,enemies:[enemy],enemySources:{'bow-target':{q:1,r:0,site:'rampaging'}},defeatedIds:[],blockedIds:[],damageUnits:[],woundsTaken:0};s=act(s,'PLAY_CARD',{uid:bow.uid,mode:'basic',discardUids:fuel.map(card=>card.uid)});expect(s.error).toBeNull();expect(s.points.ranged).toBe(4);expect(s.player.discard.map(card=>card.uid)).toEqual(fuel.map(card=>card.uid));expect(s.player.hand.map(card=>card.uid)).toContain('bow-wound');s=act(s,'RESOLVE_RANGED',{targetIds:[enemy.uid]});expect(s.player.fame).toBe(3);});
  test('Bow of Starsdawn ultimate resolves card, Unit, and Skill Ranged or Siege contributions separately',()=>{let s=createGame(),bow=artifactToHand(s,'bow-of-stars'),shot={id:'bow-shot',uid:'bow-shot',name:'Bow Shot',color:'white',type:'advanced',basic:{fireRanged:3},strong:{fireRanged:5}},unit={...unitForTest('peasants','bow-unit'),spent:false,powers:[{id:'bow-siege',effect:'iceSiege',value:4}]},skill={id:'bow-skill',name:'Bow Skill',effect:'anyCombat',value:2,used:false,roundUsed:false};s.player.hand=[bow,shot];s.player.units=[unit];s.player.skills=[skill];s.phase='combat-ranged';s.combat={enemy:{id:'foe',uid:'foe',name:'Foe',armor:99,attack:1,fame:1,traits:[]},enemies:[],defeatedIds:[],blockedIds:[]};s=act(s,'PLAY_CARD',{uid:bow.uid,mode:'strong'});expect(s.player.removed.map(card=>card.id)).toContain('bow-of-stars');s=act(s,'PLAY_CARD',{uid:shot.uid,mode:'basic'});expect(s.pendingBowAttacks[0]).toEqual({stat:'fireRanged',amount:3});expect(s.points.fireRanged).toBe(0);s=act(s,'RESOLVE_BOW_ATTACK',{mode:'double'});expect(s.points.fireRanged).toBe(6);s=act(s,'USE_UNIT',{id:unit.uid,abilityId:'bow-siege'});expect(s.pendingBowAttacks[0]).toEqual({stat:'iceSiege',amount:4});s=act(s,'RESOLVE_BOW_ATTACK',{mode:'double-ranged'});expect(s.points.iceRanged).toBe(8);s=act(s,'USE_SKILL',{id:skill.id,mode:'ranged'});expect(s.pendingBowAttacks[0]).toEqual({stat:'ranged',amount:2});s=act(s,'RESOLVE_BOW_ATTACK',{mode:'siege'});expect(s.points.siege).toBe(2);expect(s.pendingBowAttacks).toEqual([]);});
  test('Circlet of Proficiency basic invokes a once-per-turn Common Skill twice without taking it',()=>{let s=createGame(),circlet=artifactToHand(s,'ring-of-proficiency'),skill={id:'circlet-path',name:'Borrowed Path',effect:'move',value:3,cadence:'turn',description:'Move 3'};s.player.hand=[circlet];s.commonSkills=[skill];s=act(s,'PLAY_CARD',{uid:circlet.uid,mode:'basic'});expect(s.pendingCirclet).toMatchObject({mode:'basic',skillIds:[skill.id]});s=act(s,'RESOLVE_CIRCLET',{skillId:skill.id});expect(s.error).toBeNull();expect(s.points.move).toBe(6);expect(s.commonSkills.map(item=>item.id)).toContain(skill.id);expect(s.player.skills).toHaveLength(0);expect(s.player.played.map(card=>card.id)).toContain('ring-of-proficiency');});
