  test('Burning Shield rewards a successful block with Fire Attack and not a failed block',()=>{const enemy={id:'shield-target',uid:'shield-target',name:'Target',armor:6,attack:4,traits:[]};let s=createGame(),spell=spellToHand(s,'burning-shield');s.player.hand=[spell];s.phase='combat-block';s.combat={enemy:{...enemy},enemies:[{...enemy}],blockEnemies:[{...enemy}],defeatedIds:[],blockedIds:[]};s.mana=['red'];s=act(s,'PLAY_CARD',{uid:spell.uid,mode:'basic'});expect(s.points.fireBlock).toBe(4);s=act(s,'RESOLVE_BLOCK');expect(s.phase).toBe('combat-attack');expect(s.points.fireAttack).toBe(4);expect(s.bonuses.burningShield).toBeNull();s=createGame();spell=spellToHand(s,'burning-shield');s.player.hand=[spell];s.phase='combat-block';s.combat={enemy:{...enemy,attack:5},enemies:[{...enemy,attack:5}],blockEnemies:[{...enemy,attack:5}],defeatedIds:[],blockedIds:[]};s.mana=['red'];s=act(s,'PLAY_CARD',{uid:spell.uid,mode:'basic'});s=act(s,'RESOLVE_BLOCK');expect(s.points.fireAttack).toBe(0);expect(s.bonuses.burningShield).toBe('attack');});
