  test('Meditation randomly recovers two cards together and draws two over the hand limit',()=>{let s=createGame(),spell=spellToHand(s,'meditation'),discard=[0,1,2].map(index=>({id:`memory-${index}`,uid:`memory-${index}`,name:`Memory ${index}`,color:'white',basic:{move:1},strong:{move:2}}));s.player.hand=[spell];s.player.discard=discard;s.player.deck=Array.from({length:10},(_,index)=>({id:`deck-${index}`,uid:`deck-${index}`,name:`Deck ${index}`}));s.mana=['green'];s=act(s,'PLAY_CARD',{uid:spell.uid,mode:'basic'});expect(s.error).toBeNull();expect(s.pendingMeditation.uids).toHaveLength(2);expect(s.bonuses.handLimitBonus).toBe(2);const order=[...s.pendingMeditation.uids].reverse();s=act(s,'RESOLVE_MEDITATION',{placement:'top',uids:order});expect(s.player.deck.slice(0,2).map(card=>card.uid)).toEqual(order);s=act(s,'END_TURN');expect(s.player.hand).toHaveLength(7);});
