  test('Space Bending treats spaces two hexes away as adjacent and ignores rampagers',()=>{let s=createGame(),spell=spellToHand(s,'space-bending'),target=s.map.find(hex=>hex.revealed!==false&&hexDistance(s.player,hex)===2&&!hex.enemy&&Number.isFinite(TERRAIN_COST.day[hex.terrain])),rampager=s.map.find(hex=>hexDistance(s.player,hex)===1&&hexDistance(target,hex)===1);Object.assign(rampager,{site:'rampaging',enemy:{id:'watcher',uid:'space-watcher',name:'Watcher',armor:2,attack:2,fame:1,traits:[]}});s.player.hand=[spell];s.mana=['blue'];s.points.move=99;s=act(s,'PLAY_CARD',{uid:spell.uid,mode:'basic'});expect(s.error).toBeNull();expect(legalMoves(s).some(hex=>hex.q===target.q&&hex.r===target.r)).toBe(true);s=act(s,'MOVE',{q:target.q,r:target.r});expect(s.error).toBeNull();expect([s.player.q,s.player.r]).toEqual([target.q,target.r]);expect(s.phase).toBe('action');});
  test('Space Bending explores a legal tile placement two hexes away',()=>{let s=createGame(42,{exploration:true}),spell=spellToHand(s,'space-bending');s.map.filter(hex=>['starting','countryside-a','countryside-b'].includes(hex.tileId)).forEach(hex=>hex.revealed=true);s.exploredTiles=['countryside-a','countryside-b'];s.tileDeck=[s.map.find(hex=>!hex.core&&hex.revealed===false).tileId];s.player.hand=[spell];s.mana=['blue'];s.points.move=2;s=act(s,'PLAY_CARD',{uid:spell.uid,mode:'basic'});const option=explorationFromFrontier(s,2);expect(option).toBeDefined();s=act(s,'EXPLORE',{q:option.q,r:option.r});expect(s.error).toBeNull();expect(s.points.move).toBe(0);expect(s.exploredTiles).toContain(option.tileId);expect(s.map.filter(hex=>hex.tileId===option.tileId).every(hex=>hex.revealed)).toBe(true);});
  test('Time Bending returns other played cards, skips drawing, and restores itself next round',()=>{let s=createGame(),spell=spellToHand(s,'space-bending'),march=cardToHand(s,'march');s.player.hand=[spell,march];s.player.deck=Array.from({length:8},(_,index)=>({id:`reserve-${index}`,uid:`reserve-${index}`,name:`Reserve ${index}`}));s.time='night';s.mana=['blue','black'];s=act(s,'PLAY_CARD',{uid:march.uid,mode:'basic'});s=act(s,'PLAY_CARD',{uid:spell.uid,mode:'strong'});s=act(s,'END_TURN');expect(s.error).toBeNull();expect(s.player.hand.map(card=>card.id)).toEqual(['march']);expect(s.player.setAside.map(card=>card.id)).toEqual(['space-bending']);expect(s.player.timeBentTurn).toBe(true);expect(s.turn).toBe(2);s.player.deck=[];s=act(s,'END_ROUND');expect(s.round).toBe(2);expect(s.player.setAside).toEqual([]);expect([...s.player.hand,...s.player.deck].some(card=>card.id==='space-bending')).toBe(true);});
