  test('Veil of Mist grants every Unit resistance and prevents exactly one Hero Wound',()=>{let s=createGame(),spell=spellToHand(s,'mist-form'),unit={...unitForTest('peasants','mist-unit'),armor:4};s.player.hand=[spell];s.player.units=[unit];s.player.armor=2;s.time='night';s.phase='combat-block';s.combat={enemy:{id:'mist-group',name:'Group',armor:8,attack:8,traits:[]},enemies:[{id:'mist-a',uid:'mist-a',name:'Mist A',armor:4,attack:4,traits:[]},{id:'mist-b',uid:'mist-b',name:'Mist B',armor:4,attack:4,traits:[]}],blockEnemies:[{id:'mist-a',uid:'mist-a',name:'Mist A',armor:4,attack:4,traits:[]},{id:'mist-b',uid:'mist-b',name:'Mist B',armor:4,attack:4,traits:[]}],defeatedIds:[],blockedIds:[],damageUnits:[]};s.mana=['blue','black'];s=act(s,'PLAY_CARD',{uid:spell.uid,mode:'strong'});expect(s.error).toBeNull();expect(s.bonuses).toMatchObject({unitResistances:true,heroWoundImmunity:true});s=act(s,'FINISH_BLOCK');expect(s.phase).toBe('combat-damage');s=act(s,'ASSIGN_DAMAGE_UNIT',{id:unit.uid});s=act(s,'RESOLVE_DAMAGE');expect(s.player.units[0].wounded).toBe(false);expect(s.player.wounds).toBe(0);expect(s.bonuses.heroWoundImmunity).toBe(true);s=act(s,'RESOLVE_DAMAGE');expect(s.player.wounds).toBe(1);expect(s.bonuses.heroWoundImmunity).toBe(false);});
