  test('solo and cooperative games include a hidden dummy timer',()=>{const solo={...lobby,players:[lobby.players[0]]},soloState=createMultiplayerGame(solo,42),coopState=createMultiplayerGame({...lobby,scenario:'cooperative-conquest'},42),competitive=createMultiplayerGame(lobby,42),view=gameViewForPlayer(soloState,'p1');expect(soloState.dummy.deck).toHaveLength(16);expect(coopState.dummy).toBeDefined();expect(competitive.dummy).toBeUndefined();expect(view.dummy.deck).toEqual([]);expect(view.dummy.deckCount).toBe(16);});
  test('dummy turns discard three cards plus crystals matching the last card',()=>{const solo={...lobby,players:[lobby.players[0]]};let s=createMultiplayerGame(solo,42);s=reduceGame(s,{type:'SELECT_TACTIC',id:'early-bird',playerId:'p1'});s.turnOrder=['p1','dummy'];s.activePlayerId='p1';s.dummy.deck=[0,1,2,3].map(index=>({id:`red-${index}`,color:'red'}));s.dummy.discard=[];s.dummy.crystals.red=1;s.players[0].cardsPlayedThisTurn=1;s=reduceGame(s,{type:'END_TURN',playerId:'p1'});expect(s.dummy.deck).toHaveLength(0);expect(s.dummy.discard).toHaveLength(4);expect(s.activePlayerId).toBe('p1');});
  test('an empty dummy announces the round and grants the real player one final turn',()=>{const solo={...lobby,players:[lobby.players[0]]};let s=createMultiplayerGame(solo,42);s=reduceGame(s,{type:'SELECT_TACTIC',id:'early-bird',playerId:'p1'});s.turnOrder=['p1','dummy'];s.activePlayerId='p1';s.dummy.deck=[];s.players[0].cardsPlayedThisTurn=1;s=reduceGame(s,{type:'END_TURN',playerId:'p1'});expect(s.roundEndTurnsRemaining).toBe(1);expect(s.activePlayerId).toBe('p1');s.players[0].cardsPlayedThisTurn=1;s=reduceGame(s,{type:'END_TURN',playerId:'p1'});expect(s.round).toBe(2);expect(s.phase).toBe('tactic');});
  test('round refresh feeds the lowest advanced action and an uncapped spell-color crystal to the dummy',()=>{const solo={...lobby,players:[lobby.players[0]]};let s=createMultiplayerGame(solo,42),retiredAction=s.offer.advanced[0],retiredSpell=s.offer.spells[0];s.dummy.crystals[retiredSpell.color]=3;s=reduceGame(s,{type:'SELECT_TACTIC',id:'early-bird',playerId:'p1'});s.players[0].deck=[];s.players[0].hand=[];s=reduceGame(s,{type:'END_ROUND',playerId:'p1'});expect([...s.dummy.deck,...s.dummy.discard].some(card=>card.id===retiredAction.id)).toBe(true);expect(s.dummy.crystals[retiredSpell.color]).toBe(4);});
  test('solo removes both used tactics before that time of day returns',()=>{const solo={...lobby,players:[lobby.players[0]]};let s=createMultiplayerGame(solo,42);s=reduceGame(s,{type:'SELECT_TACTIC',id:'early-bird',playerId:'p1'});const dummyId=s.dummy.tactic.id;s.players[0].deck=[];s.players[0].hand=[];s=reduceGame(s,{type:'END_ROUND',playerId:'p1'});expect(s.removedTactics.day).toEqual(expect.arrayContaining(['early-bird',dummyId]));s.time='day';s=reduceGame(s,{type:'SELECT_TACTIC',id:'early-bird',playerId:'p1'});expect(s.error).toMatch(/unavailable/i);});
  test('cooperative host retires one real tactic before advancing the round',()=>{let s=pickTactics(createMultiplayerGame({...lobby,scenario:'cooperative-conquest'},42));const actor=s.activePlayerId;s.players.find(player=>player.id===actor).deck=[];s.players.find(player=>player.id===actor).hand=[];s=reduceGame(s,{type:'END_ROUND',playerId:actor});const other=s.activePlayerId;s.players.find(player=>player.id===other).cardsPlayedThisTurn=1;s=reduceGame(s,{type:'END_TURN',playerId:other});expect(s.phase).toBe('tactic-removal');expect(s.activePlayerId).toBe('p1');s=reduceGame(s,{type:'REMOVE_TACTIC',id:'early-bird',playerId:'p1'});expect(s.round).toBe(2);expect(s.phase).toBe('tactic');expect(s.removedTactics.day).toContain('early-bird');});
  test('only the active player can resolve private end-turn rewards before turn order advances',()=>{let s=pickTactics(createMultiplayerGame(lobby,42));s.pendingRewards.push({type:'crystals',count:2,source:'Monster Den'});s.player.cardsPlayedThisTurn=1;s=reduceGame(s,{type:'END_TURN',playerId:'p1'});expect(s.phase).toBe('end-rewards');expect(s.activePlayerId).toBe('p1');expect(gameViewForPlayer(s,'p2').pendingRewards).toEqual([]);s=reduceGame(s,{type:'PREPARE_REWARD',playerId:'p2'});expect(s.error).toMatch(/not your turn/i);s=reduceGame(s,{type:'PREPARE_REWARD',playerId:'p1'});const gold=s.pendingRewards[0].rolls.filter(color=>color==='gold').length;s=reduceGame(s,{type:'CLAIM_REWARD',colors:Array(gold).fill('blue'),playerId:'p1'});expect(s.pendingRewards).toHaveLength(0);expect(s.phase).toBe('action');expect(s.activePlayerId).toBe('p2');});
