  test('Power of Pain plays its Wound and Healing Ritual transfers one of two Wounds to a closest rival',()=>{let s=createGame(76,{character:'arythea'}),wound={id:'wound',uid:'pain-wound',name:'Wound',color:'wound',basic:{},strong:{}};s.player.hand=[wound];s.player.wounds=1;s.player.skills=[{...BASE_ARYTHEA_SKILLS.find(skill=>skill.id==='power-of-pain'),used:false,roundUsed:false}];s=act(s,'USE_SKILL',{id:'power-of-pain',woundUid:wound.uid,mode:'move'});expect(s.points.move).toBe(2);expect(s.player.played.map(card=>card.uid)).toContain(wound.uid);const aryLobby={id:'ARY-RITUAL',scenario:'full-conquest',players:[{id:'p1',name:'Arythea',character:'arythea'},{id:'p2',name:'Near',character:'tovak'},{id:'p3',name:'Far',character:'goldyx'}]};s=pickTactics(createMultiplayerGame(aryLobby,76),{p1:'early-bird',p2:'rethink',p3:'planning'});const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),p3=s.players.find(player=>player.id==='p3'),wounds=[1,2].map(index=>({id:'wound',uid:`ritual-${index}`,name:'Wound',color:'wound',basic:{},strong:{}}));Object.assign(p1,{q:0,r:0,wounds:2,hand:wounds,skills:[{...BASE_ARYTHEA_SKILLS.find(skill=>skill.id==='healing-ritual'),used:false,roundUsed:false}]});Object.assign(p2,{q:1,r:0});Object.assign(p3,{q:3,r:0});s=reduceGame(s,{type:'USE_SKILL',id:'healing-ritual',woundUids:wounds.map(card=>card.uid),recipientId:'p3',playerId:'p1'});expect(s.error).toMatch(/closest/i);s=reduceGame(s,{type:'USE_SKILL',id:'healing-ritual',woundUids:wounds.map(card=>card.uid),recipientId:'p2',playerId:'p1'});expect(s.players.find(player=>player.id==='p1').wounds).toBe(0);expect(s.players.find(player=>player.id==='p2').wounds).toBe(1);expect(s.players.find(player=>player.id==='p2').discard.some(card=>card.id==='wound')).toBe(true);});
  test('Arythea Motivation remains usable during combat and grants red mana only at strictly lowest Fame',()=>{let s=createGame(77,{character:'arythea'});s.player.skills=[{...BASE_ARYTHEA_SKILLS.find(skill=>skill.id==='arythea-motivation'),used:false,roundUsed:false}];s.phase='combat-block';s.combat={enemy:{armor:5,traits:[]}};const before=s.player.hand.length;s=act(s,'USE_SKILL',{id:'arythea-motivation'});expect(s.error).toBeNull();expect(s.player.hand).toHaveLength(before+2);expect(s.mana).toContain('red');});
