  test('Source Freeze blocks rivals usual die, permits additional dice, and rewards Goldyx next turn',()=>{const goldLobby={id:'FREEZE',scenario:'full-conquest',players:[{id:'p1',name:'Goldyx',character:'goldyx'},{id:'p2',name:'Tovak',character:'tovak'}]};let s=pickTactics(createMultiplayerGame(goldLobby,82),{p1:'early-bird',p2:'rethink'}),gold=s.players.find(player=>player.id==='p1');gold.skills=[{...BASE_GOLDYX_SKILLS.find(skill=>skill.id==='source-freeze'),used:false,roundUsed:false}];s=reduceGame(s,{type:'USE_SKILL',id:'source-freeze',playerId:'p1'});expect(s.sourceFreeze).toMatchObject({ownerId:'p1',ready:false});s=reduceGame(s,{type:'END_TURN',discardUids:[gold.hand[0].uid],playerId:'p1'});let die=s.source.find(item=>['blue','red','green','white'].includes(item.color))||s.source[0];die.color='blue';s=reduceGame(s,{type:'TAKE_SOURCE',id:die.id,playerId:'p2'});expect(s.error).toMatch(/Source Freeze/i);s.playerResources.p2.bonuses.extraSourceUses=1;s=reduceGame(s,{type:'TAKE_SOURCE',id:die.id,playerId:'p2'});expect(s.error).toBeNull();expect(s.playerResources.p2.bonuses.extraSourceUses).toBe(0);s=reduceGame(s,{type:'END_TURN',discardUids:[s.players.find(player=>player.id==='p2').hand[0].uid],playerId:'p2'});expect(s.sourceFreeze.ready).toBe(true);s.source[0].color='green';const before=s.players.find(player=>player.id==='p1').crystals.green;s=reduceGame(s,{type:'USE_SKILL',id:'source-freeze',color:'green',playerId:'p1'});expect(s.error).toBeNull();expect(s.sourceFreeze).toBeNull();expect(s.players.find(player=>player.id==='p1').crystals.green).toBe(before+1);});
  test('Norowas uses his nine printed personal Skills plus Prayer of Weather only in competitive games',()=>{const competitive=createMultiplayerGame({id:'NOROWAS',scenario:'full-conquest',players:[{id:'p1',name:'Norowas',character:'norowas'},{id:'p2',name:'Tovak',character:'tovak'}]},83),solo=createMultiplayerGame({id:'NOROWAS-SOLO',scenario:'full-conquest',players:[{id:'p1',name:'Norowas',character:'norowas'}]},83);expect(competitive.playerResources.p1.skillDeck.map(skill=>skill.id).sort()).toEqual(BASE_NOROWAS_SKILLS.map(skill=>skill.id).sort());expect(solo.playerResources.p1.skillDeck.map(skill=>skill.id).sort()).toEqual(BASE_NOROWAS_SKILLS.slice(0,-1).map(skill=>skill.id).sort());});
  test('Norowas movement, ranged, negotiation, and mana Skills use their printed values',()=>{let s=createGame(84,{character:'norowas'});s.player.skills=BASE_NOROWAS_SKILLS.filter(skill=>['forward-march','bright-negotiation','leaves-in-the-wind','whispers-in-the-treetops'].includes(skill.id)).map(skill=>({...skill,used:false,roundUsed:false}));s.player.units=[{id:'ready-a',uid:'ready-a',spent:false,wounded:false},{id:'ready-b',uid:'ready-b',spent:false,wounded:false},{id:'spent',uid:'spent',spent:true,wounded:false},{id:'wounded',uid:'wounded',spent:false,wounded:true}];s=act(s,'USE_SKILL',{id:'forward-march'});s=act(s,'USE_SKILL',{id:'bright-negotiation'});s=act(s,'USE_SKILL',{id:'leaves-in-the-wind'});s=act(s,'USE_SKILL',{id:'whispers-in-the-treetops'});expect(s.points).toMatchObject({move:2,influence:3});expect(s.player.crystals).toMatchObject({green:1,blue:1});expect(s.mana.filter(color=>color==='white')).toHaveLength(2);s=createGame(85,{character:'norowas'});s.player.skills=[{...BASE_NOROWAS_SKILLS.find(skill=>skill.id==='day-sharpshooting'),used:false,roundUsed:false}];s.phase='combat-ranged';s.combat={enemy:{armor:5,traits:[]}};s=act(s,'USE_SKILL',{id:'day-sharpshooting'});expect(s.points.ranged).toBe(2);});
  test('Inspiration readies or heals one Unit and Leadership preserves the Unit attack element',()=>{let s=createGame(86,{character:'norowas'}),unit={id:'leaders',uid:'leaders',name:'Leaders',level:2,armor:4,spent:true,wounded:true,woundCount:1,powers:[{id:'flame-wall',effect:'fireBlock',value:3}]};s.player.units=[unit];s.player.skills=[{...BASE_NOROWAS_SKILLS.find(skill=>skill.id==='inspiration'),used:false,roundUsed:false},{...BASE_NOROWAS_SKILLS.find(skill=>skill.id==='leadership'),used:false,roundUsed:false}];s=act(s,'USE_SKILL',{id:'inspiration',unitId:unit.uid,mode:'heal'});expect(s.player.units[0].wounded).toBe(false);s.player.units[0].spent=false;s.phase='combat-block';s.combat={enemy:{armor:5,traits:[]}};s=act(s,'USE_UNIT',{id:unit.uid,abilityId:'flame-wall',leadership:true});expect(s.error).toBeNull();expect(s.points.fireBlock).toBe(6);expect(s.player.skills.find(skill=>skill.id==='leadership').used).toBe(true);});
  test('Bonds of Loyalty adds its offer and slot, discounts its permanent Unit, and permits underground use',()=>{let s=createGame(87,{character:'norowas'}),skill={...BASE_NOROWAS_SKILLS.find(item=>item.id==='bonds-of-loyalty'),used:false,roundUsed:false},beforeOffer=s.offer.units.length,beforeDeck=s.decks.regularUnits.length,beforeCommand=s.player.command;s.skillChoices=[skill];const advanced=s.offer.advanced[0];s=act(s,'SELECT_SKILL',{id:skill.id,advancedId:advanced.id});expect(s.player.command).toBe(beforeCommand+1);expect(s.offer.units).toHaveLength(beforeOffer+2);expect(s.decks.regularUnits).toHaveLength(beforeDeck-2);const unit=s.offer.units.find(item=>item.sites.some(site=>s.map.some(hex=>hex.site===site)))||s.offer.units[0],site=s.map.find(hex=>unit.sites.includes(hex.site));Object.assign(s.player,{q:site.q,r:site.r});site.revealed=true;s.points.influence=99;s=act(s,'INTERACT',{kind:'recruit',id:unitKey(unit),bond:true});const bonded=s.player.units.find(item=>item.bonded);expect(bonded).toBeDefined();expect(s.player.bondedUnitId).toBe(unitKey(bonded));bonded.spent=false;bonded.wounded=false;bonded.powers=[{id:'bond-attack',effect:'attack',value:2}];s.phase='combat-attack';s.combat={kind:'adventure',q:site.q,r:site.r,enemy:{armor:5,traits:[]}};site.site='dungeon';s=act(s,'USE_UNIT',{id:unitKey(bonded),abilityId:'bond-attack'});expect(s.error).toBeNull();expect(s.points.attack).toBe(2);});
  test('Prayer of Weather lowers Norowas terrain and raises a rival until his next turn',()=>{const norLobby={id:'WEATHER',scenario:'full-conquest',players:[{id:'p1',name:'Norowas',character:'norowas'},{id:'p2',name:'Tovak',character:'tovak'}]};let s=pickTactics(createMultiplayerGame(norLobby,88),{p1:'early-bird',p2:'rethink'}),target=s.map.find(hex=>hexDistance(s.player,hex)===1);Object.assign(target,{revealed:true,terrain:'plains',site:null,enemy:null});s.players.find(player=>player.id==='p1').skills=[{...BASE_NOROWAS_SKILLS.find(skill=>skill.id==='prayer-of-weather'),used:false,roundUsed:false}];s=reduceGame(s,{type:'USE_SKILL',id:'prayer-of-weather',playerId:'p1'});expect(legalMoves(s).find(hex=>hex.q===target.q&&hex.r===target.r).cost).toBe(1);s=reduceGame(s,{type:'END_TURN',discardUids:[s.players.find(player=>player.id==='p1').hand[0].uid],playerId:'p1'});expect(legalMoves(s).find(hex=>hex.q===target.q&&hex.r===target.r).cost).toBe(3);s=reduceGame(s,{type:'END_TURN',discardUids:[s.players.find(player=>player.id==='p2').hand[0].uid],playerId:'p2'});expect(s.prayerWeather).toBeNull();});
  test('Mana Exploit wounds rivals once per different off-color mana until Tovak next acts',()=>{let s=started('full-conquest'),p1=s.players.find(player=>player.id==='p1'),skill={...BASE_TOVAK_SKILLS.find(item=>item.id==='mana-exploit'),used:false,roundUsed:false};p1.skills=[skill];s=reduceGame(s,{type:'USE_SKILL',id:'mana-exploit',color:'blue',playerId:'p1'});expect(s.mana).toContain('blue');s=reduceGame(s,{type:'END_TURN',discardUids:[p1.hand[0].uid],playerId:'p1'});s.players.find(player=>player.id==='p2').hand=[{id:'red-move-a',uid:'red-move-a',name:'Red A',color:'red',basic:{move:1},strong:{move:2}},{id:'red-move-b',uid:'red-move-b',name:'Red B',color:'red',basic:{move:1},strong:{move:2}},{id:'green-move',uid:'green-move',name:'Green',color:'green',basic:{move:1},strong:{move:2}}];s.mana=['red','red','green'];s=reduceGame(s,{type:'PLAY_CARD',uid:'red-move-a',mode:'strong',playerId:'p2'});s=reduceGame(s,{type:'PLAY_CARD',uid:'red-move-b',mode:'strong',playerId:'p2'});s=reduceGame(s,{type:'PLAY_CARD',uid:'green-move',mode:'strong',playerId:'p2'});expect(s.players.find(player=>player.id==='p2').wounds).toBe(2);expect(s.manaExploits[0].woundedColors.p2.sort()).toEqual(['green','red']);s=reduceGame(s,{type:'END_TURN',discardUids:[],playerId:'p2'});expect(s.activePlayerId).toBe('p1');expect(s.manaExploits).toEqual([]);});
  test('Tovak Motivation grants blue mana only when his Fame is strictly lowest',()=>{let s=started('full-conquest'),p1=s.players.find(player=>player.id==='p1');p1.skills=[{...TOVAK_SKILLS.find(skill=>skill.id==='motivation'),used:false,roundUsed:false}];s=reduceGame(s,{type:'USE_SKILL',id:'motivation',playerId:'p1'});expect(s.mana).not.toContain('blue');s=createMultiplayerGame({...lobby('full-conquest'),players:[{id:'p1',name:'One',character:'tovak'}]},72);s=pickTactics(s,{p1:'early-bird'});s.player.skills=[{...TOVAK_SKILLS.find(skill=>skill.id==='motivation'),used:false,roundUsed:false}];s=reduceGame(s,{type:'USE_SKILL',id:'motivation',playerId:'p1'});expect(s.mana).toContain('blue');});
  test('scenario setup uses official city counts and reveal-order levels without revealing garrisons early',()=>{const full=createMultiplayerGame(lobby('full-conquest'),77),blitz=createMultiplayerGame(lobby('blitz-conquest'),77),coop=createMultiplayerGame(lobby('cooperative-conquest'),77),blitzCoop2=createMultiplayerGame(lobby('blitz-cooperation'),77),blitzCoop3=createMultiplayerGame({...lobby('blitz-cooperation'),players:[...lobby('blitz-cooperation').players,{id:'p3',name:'Three',character:'goldyx'}]},77),solo=createMultiplayerGame({id:'SOLO',scenario:'full-conquest',players:[{id:'p1',name:'One',character:'tovak'}]},77),cities=state=>state.map.filter(hex=>hex.site==='city');expect(cities(full).map(hex=>hex.level)).toEqual([4,4]);expect(cities(full).every(hex=>hex.enemy===null&&hex.enemies.length===0)).toBe(true);expect(cities(blitz).map(hex=>hex.level)).toEqual([3,3]);expect(coop.cityLevelDeck).toEqual([5,5,8]);expect(blitzCoop2.cityLevelDeck).toEqual([5,8]);expect(blitzCoop3.cityLevelDeck).toEqual([5,8,11]);expect(solo.cityLevelDeck).toEqual([5,8]);expect([...cities(coop),...cities(blitzCoop2),...cities(blitzCoop3),...cities(solo)].every(hex=>hex.level===null)).toBe(true);expect(blitz.players.every(player=>player.fame===1&&player.reputation===2)).toBe(true);expect(blitz.source).toHaveLength(5);expect(blitz.offer.units).toHaveLength(5);expect(blitzCoop2).toMatchObject({maxRounds:4});expect(blitzCoop2.players.every(player=>player.fame===1&&player.reputation===2)).toBe(true);expect(blitzCoop2.source).toHaveLength(5);expect(blitzCoop2.offer.units).toHaveLength(5);expect(blitzCoop2.dummy).toBeDefined();expect([...blitzCoop2.offer.spells,...blitzCoop2.decks.spells].some(card=>card.competitive)).toBe(false);});
  test('exploring city tiles assigns levels in reveal order and draws the printed garrison colors',()=>{let s=pickTactics(createMultiplayerGame({id:'SOLO-CITIES',scenario:'full-conquest',players:[{id:'p1',name:'One',character:'tovak'}]},77),{p1:'early-bird'}),city=s.map.find(hex=>hex.site==='city'),categories=CITY_GARRISONS[city.cityColor][5],before=Object.fromEntries([...new Set(categories)].map(category=>[category,s.enemyDecks[category].length]));s.map.filter(hex=>!hex.core).forEach(hex=>{hex.revealed=true;});s.tileDeck=[city.tileId];Object.assign(s.player,{q:city.q-1,r:city.r});s.points.move=2;s=reduceGame(s,{type:'EXPLORE',q:city.q,r:city.r,playerId:'p1'});city=s.map.find(hex=>hex.site==='city'&&hex.revealed);expect(s.error).toBeNull();expect(city.level).toBe(5);expect(s.cityLevelDeck).toEqual([8]);expect(city.enemies.map(enemy=>enemy.category)).toEqual(categories);expect(city.enemyFaceDown).toBe(false);for(const category of new Set(categories))expect(s.enemyDecks[category]).toHaveLength(before[category]-categories.filter(item=>item===category).length);});
  test('Blitz Cooperation uses team rules for assaults, PvP, victory, and scoring',()=>{let s=started('blitz-cooperation');s.map.forEach(hex=>hex.revealed=true);const cities=s.map.filter(hex=>hex.site==='city'),city=cities[0],assignments={p1:1,p2:CITY_GARRISONS[city.cityColor][city.level||s.cityLevelDeck[0]].length-1};Object.assign(s.players.find(player=>player.id==='p1'),{q:city.q-1,r:city.r});Object.assign(s.players.find(player=>player.id==='p2'),{q:city.q,r:city.r-1});s.points.move=99;s=reduceGame(s,{type:'START_COOPERATIVE_ASSAULT',q:city.q,r:city.r,assignments,playerId:'p1'});expect(s.cooperativeAssault).toMatchObject({stage:'proposal',leaderId:'p1'});s=reduceGame(s,{type:'TEAM_DECLINE',playerId:'p2'});s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});expect(s.error).toMatch(/PvP is disabled/i);cities[0].conquered=true;cities[0].ownerId='p1';const score=calculateScore(s);expect(score.winner).toBeNull();expect(score.scenarioBonus).not.toBeNull();expect(score.missionSuccess).toBe(false);});
  test('defeated map enemies enter their category discard pile',()=>{let s=started('full-conquest'),rampager=s.map.find(hex=>hex.site==='rampaging'&&hex.revealed&&hex.enemy);placeNextTo(s.player,rampager);s=reduceGame(s,{type:'START_COMBAT',q:rampager.q,r:rampager.r,playerId:s.activePlayerId});s.points.ranged=99;s.points.siege=99;s=reduceGame(s,{type:'RESOLVE_RANGED',playerId:s.activePlayerId});expect(s.enemyDiscards.orc).toHaveLength(1);expect(s.enemyDiscards.orc[0].category).toBe('orc');});
  test('round refresh keeps Blitz bonuses and clears spent Round Order tokens',()=>{let s=started('blitz-conquest'),actor=s.activePlayerId;s.players.forEach(player=>{player.skipNextTurn=true;player.roundOrderFaceDown=true;});s.players.find(player=>player.id===actor).skipNextTurn=false;s.players.find(player=>player.id===actor).deck=[];s.players.find(player=>player.id===actor).hand=[];s=reduceGame(s,{type:'END_ROUND',playerId:actor});expect(s.round).toBe(2);expect(s.source).toHaveLength(5);expect(s.offer.units).toHaveLength(5);expect(s.players.every(player=>!player.skipNextTurn&&!player.roundOrderFaceDown)).toBe(true);});
  test('cooperative city assault requires consent, consumes invited turns, and resolves assigned battles',()=>{let s=started('cooperative-conquest');s.map.forEach(hex=>hex.revealed=true);const city=s.map.find(hex=>hex.site==='city'),assignments={p1:1,p2:CITY_GARRISONS[city.cityColor][city.level||s.cityLevelDeck[0]].length-1};Object.assign(s.players.find(player=>player.id==='p1'),{q:city.q-1,r:city.r});Object.assign(s.players.find(player=>player.id==='p2'),{q:city.q,r:city.r-1});s.points.move=9;s=reduceGame(s,{type:'START_COOPERATIVE_ASSAULT',q:city.q,r:city.r,assignments,playerId:'p1'});expect(s.cooperativeAssault.stage).toBe('proposal');expect(s.players.find(player=>player.id==='p1').reputation).toBe(0);s=reduceGame(s,{type:'TEAM_ACCEPT',playerId:'p2'});expect(s.phase).toBe('cooperative-entry');expect(s.players.find(player=>player.id==='p1').reputation).toBe(-1);expect(s.players.find(player=>player.id==='p2').roundOrderFaceDown).toBe(true);expect(s.players.find(player=>player.id==='p2').skipNextTurn).toBe(true);expect(s.players.find(player=>player.id==='p2').reputation).toBe(-1);s=reduceGame(s,{type:'TEAM_ENTER',playerId:'p1'});s.combat.defeatedIds=s.combat.enemies.map(enemy=>enemy.uid||enemy.id);s.phase='combat-attack';s=reduceGame(s,{type:'END_COMBAT',playerId:'p1'});expect(s.activePlayerId).toBe('p2');s.points.move=9;s=reduceGame(s,{type:'TEAM_ENTER',playerId:'p2'});s.combat.defeatedIds=s.combat.enemies.map(enemy=>enemy.uid||enemy.id);s.phase='combat-attack';s=reduceGame(s,{type:'END_COMBAT',playerId:'p2'});expect(s.map.find(hex=>hex.q===city.q&&hex.r===city.r).conquered).toBe(true);expect(s.players.every(player=>player.assaults===1)).toBe(true);expect(s.players.every(player=>player.q===city.q&&player.r===city.r)).toBe(true);});
  test('joint assault participants recover and end their advanced turns in sequence',()=>{let s=started('cooperative-conquest');const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),heal={id:'joint-heal',uid:'joint-heal-1',name:'Joint healing',color:'green',basic:{heal:2},strong:{heal:4}};p1.hand=[heal,{id:'wound',uid:'joint-wound',name:'Wound'}];p1.wounds=1;p1.turnAction='combat';p2.skipNextTurn=true;p2.roundOrderFaceDown=true;s.cooperativeAssault={leaderId:'p1',invited:['p1','p2'],stage:'after',afterOrder:['p1','p2'],afterIndex:0,resources:{p1:{points:{...s.points},mana:[],sourceTaken:false},p2:{points:{...s.points},mana:[],sourceTaken:false}}};s.phase='cooperative-after';s.activePlayerId='p1';s.player=p1;s=reduceGame(s,{type:'TEAM_PLAY_AFTER',uid:heal.uid,mode:'basic',playerId:'p1'});expect(s.points.heal).toBe(2);s=reduceGame(s,{type:'TEAM_SPEND_HEAL',playerId:'p1'});expect(s.players.find(player=>player.id==='p1').wounds).toBe(0);s=reduceGame(s,{type:'TEAM_END_AFTER',playerId:'p1'});expect(s.activePlayerId).toBe('p2');expect(s.phase).toBe('cooperative-after');s=reduceGame(s,{type:'TEAM_END_AFTER',playerId:'p2'});expect(s.cooperativeAssault).toBeNull();expect(s.phase).toBe('action');expect(s.players.find(player=>player.id==='p1').discard.some(card=>card.uid===heal.uid)).toBe(true);expect(s.players.find(player=>player.id==='p2').skipNextTurn).toBe(false);});
  test('a joint-assault participant chooses an earned Skill before their advanced turn finishes',()=>{let s=started('cooperative-conquest');const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2');p2.fame=3;p2.skipNextTurn=true;p2.roundOrderFaceDown=true;s.cooperativeAssault={leaderId:'p1',invited:['p1','p2'],stage:'after',afterOrder:['p1','p2'],afterIndex:0,resources:{p1:{points:{...s.points},mana:[],sourceTaken:false},p2:{points:{...s.points},mana:[],sourceTaken:false}}};s.phase='cooperative-after';s.activePlayerId='p1';s.player=p1;s=reduceGame(s,{type:'TEAM_END_AFTER',playerId:'p1'});s=reduceGame(s,{type:'TEAM_END_AFTER',playerId:'p2'});expect(s.phase).toBe('level-up');expect(s.levelUpContext).toMatchObject({type:'cooperative-after',playerId:'p2'});const skill=s.skillChoices[0];s=reduceGame(s,{type:'SELECT_SKILL',id:skill.id,advancedId:s.offer.advanced[0].id,playerId:'p2'});expect(s.cooperativeAssault).toBeNull();expect(s.phase).toBe('action');expect(s.players.find(player=>player.id==='p2').skills.some(item=>item.id===skill.id)).toBe(true);});
  test('a nonleader resolves Banner of Protection before joint-assault cleanup advances',()=>{let s=started('cooperative-conquest'),p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),banner=s.decks.artifacts.splice(s.decks.artifacts.findIndex(card=>card.id==='banner-of-protection'),1)[0],wound={id:'wound',uid:'joint-protection-wound',name:'Wound'};Object.assign(p2,{played:[banner],hand:[wound],wounds:1,woundsReceivedThisTurn:[wound.uid],cardsPlayedThisTurn:1,skipNextTurn:true,roundOrderFaceDown:true});s.playerResources.p2.bonuses.bannerProtection=true;s.cooperativeAssault={leaderId:'p1',invited:['p1','p2'],stage:'after',afterOrder:['p1','p2'],afterIndex:0,resources:{p1:{points:{...s.points},mana:[],sourceTaken:false},p2:{points:{...s.points},mana:[],sourceTaken:false}}};s.phase='cooperative-after';s.activePlayerId='p1';s.player=p1;s=reduceGame(s,{type:'TEAM_END_AFTER',playerId:'p1'});s=reduceGame(s,{type:'TEAM_END_AFTER',playerId:'p2'});expect(s.pendingBannerProtection).toMatchObject({continuation:'cooperative-after',woundUids:[wound.uid]});expect(s.cooperativeAssault).not.toBeNull();s=reduceGame(s,{type:'RESOLVE_BANNER_PROTECTION',removeWounds:true,playerId:'p2'});expect(s.error).toBeNull();expect(s.pendingBannerProtection).toBeNull();expect(s.players.find(player=>player.id==='p2')).toMatchObject({wounds:0,woundsReceivedThisTurn:[]});expect(s.players.find(player=>player.id==='p2').removed.map(card=>card.id)).toContain('banner-of-protection');expect(s.cooperativeAssault).toBeNull();});
  test('declining a cooperative assault cancels it without spending Move or Reputation',()=>{let s=started('cooperative-conquest');s.map.forEach(hex=>hex.revealed=true);const city=s.map.find(hex=>hex.site==='city'),assignments={p1:1,p2:CITY_GARRISONS[city.cityColor][city.level||s.cityLevelDeck[0]].length-1};Object.assign(s.players.find(player=>player.id==='p1'),{q:city.q-1,r:city.r});Object.assign(s.players.find(player=>player.id==='p2'),{q:city.q,r:city.r-1});s.points.move=9;s=reduceGame(s,{type:'START_COOPERATIVE_ASSAULT',q:city.q,r:city.r,assignments,playerId:'p1'});s=reduceGame(s,{type:'TEAM_DECLINE',playerId:'p2'});expect(s.phase).toBe('action');expect(s.points.move).toBe(9);expect(s.players.every(player=>player.reputation===0)).toBe(true);});
