  test('PvP entry costs Move and combat alternates into melee after two passes',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);Object.assign(s.players.find(player=>player.id==='p1'),{q:0,r:0});Object.assign(s.players.find(player=>player.id==='p2'),{q:1,r:0});s.points.move=2;s.points.attack=6;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});expect(s.phase).toBe('pvp-attend');expect([s.players.find(player=>player.id==='p1').q,s.players.find(player=>player.id==='p1').r]).toEqual([1,0]);expect(s.points.move).toBe(0);s=reduceGame(s,{type:'PVP_ATTEND',mode:'partial',playerId:'p2'});expect(s.pvp.currentAttackerId).toBe('p2');s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p1'});expect(s.phase).toBe('pvp-melee');expect(s.pvp.currentAttackerId).toBe('p1');s=reduceGame(s,{type:'PVP_USE_PREPARED',playerId:'p1'});s=reduceGame(s,{type:'PVP_DECLARE_ATTACK',playerId:'p1'});s=reduceGame(s,{type:'PVP_RESOLVE_BLOCK',playerId:'p1'});s=reduceGame(s,{type:'PVP_FORCE_RETREAT',q:1,r:-1,playerId:'p1'});expect(s.phase).toBe('action');expect(s.players.find(player=>player.id==='p1').pvpWins).toBe(1);expect([s.players.find(player=>player.id==='p2').q,s.players.find(player=>player.id==='p2').r]).toEqual([1,-1]);});
  test('a drawn PvP combat sends the aggressor back to the attack origin',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);Object.assign(s.players.find(player=>player.id==='p1'),{q:0,r:0});Object.assign(s.players.find(player=>player.id==='p2'),{q:1,r:0});s.points.move=2;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});expect(s.pvp.aggressorOrigin).toEqual({q:0,r:0});s=reduceGame(s,{type:'PVP_ATTEND',mode:'partial',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p1'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p1'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});expect(s.phase).toBe('pvp-withdraw');s=reduceGame(s,{type:'PVP_WITHDRAW',q:1,r:-1,playerId:'p1'});expect(s.error).toMatch(/space from which/i);expect(s.phase).toBe('pvp-withdraw');s=reduceGame(s,{type:'PVP_WITHDRAW',q:0,r:0,playerId:'p1'});expect(s.error).toBeNull();expect(s.phase).toBe('action');expect([s.players.find(player=>player.id==='p1').q,s.players.find(player=>player.id==='p1').r]).toEqual([0,0]);expect(s.players.every(player=>player.pvpWins===0)).toBe(true);});
  test('PvP draw removes the attack step before a later forced withdrawal',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),origin=s.map.find(hex=>hex.q===0&&hex.r===0),safe=s.map.find(hex=>hex.q===1&&hex.r===-1);Object.assign(origin,{terrain:'mountain'});Object.assign(safe,{terrain:'plains',site:null,conquered:false});Object.assign(p1,{q:0,r:0,moveHistory:[{q:safe.q,r:safe.r}]});Object.assign(p2,{q:1,r:0});s.points.move=2;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});s=reduceGame(s,{type:'PVP_ATTEND',mode:'partial',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p1'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p1'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_WITHDRAW',q:0,r:0,playerId:'p1'});expect(s.players.find(player=>player.id==='p1').moveHistory).toEqual([{q:safe.q,r:safe.r}]);const discardUid=s.players.find(player=>player.id==='p1').hand[0].uid;s=reduceGame(s,{type:'END_TURN',discardUids:[discardUid],playerId:'p1'});const withdrawn=s.players.find(player=>player.id==='p1');expect([withdrawn.q,withdrawn.r]).toEqual([safe.q,safe.r]);expect(withdrawn.wounds).toBe(1);});
  test('PvP is forbidden on portals and after the round is announced',()=>{let s=started('full-conquest');Object.assign(s.players.find(player=>player.id==='p1'),{q:1,r:0});Object.assign(s.players.find(player=>player.id==='p2'),{q:0,r:0});s.points.move=9;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});expect(s.error).toMatch(/portal or city/i);s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);Object.assign(s.players.find(player=>player.id==='p2'),{q:1,r:0});s.roundEndTurnsRemaining=1;s.points.move=9;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});expect(s.error).toMatch(/end-of-round/i);});
  test('full PvP attendance protects the defender and skips their next turn',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);Object.assign(s.players.find(player=>player.id==='p1'),{q:0,r:0});Object.assign(s.players.find(player=>player.id==='p2'),{q:1,r:0});s.points.move=2;s.points.attack=6;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});s=reduceGame(s,{type:'PVP_ATTEND',mode:'full',playerId:'p2'});expect(s.players.find(player=>player.id==='p2').roundOrderFaceDown).toBe(true);s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p1'});s=reduceGame(s,{type:'PVP_USE_PREPARED',playerId:'p1'});s=reduceGame(s,{type:'PVP_DECLARE_ATTACK',playerId:'p1'});s=reduceGame(s,{type:'PVP_RESOLVE_BLOCK',playerId:'p1'});s=reduceGame(s,{type:'PVP_FORCE_RETREAT',q:1,r:-1,playerId:'p1'});expect(s.phase).toBe('pvp-after');s=reduceGame(s,{type:'PVP_END_REACTION',playerId:'p2'});const discardUid=s.players.find(player=>player.id==='p1').hand[0].uid;s=reduceGame(s,{type:'END_TURN',discardUids:[discardUid],playerId:'p1'});expect(s.activePlayerId).toBe('p1');expect(s.players.find(player=>player.id==='p2').skipNextTurn).toBe(false);expect(s.players.find(player=>player.id==='p2').roundOrderFaceDown).toBe(false);});
  test('a fully attending PvP defender may heal before completing end-of-turn processing',()=>{let s=started('full-conquest');const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),heal={id:'post-heal',uid:'post-heal-1',name:'Post-combat healing',color:'green',basic:{heal:2},strong:{heal:4}};Object.assign(p1,{q:0,r:0});Object.assign(p2,{q:0,r:0,wounds:1,hand:[heal,{id:'wound',uid:'post-wound',name:'Wound'}]});s.pvp={attackerId:'p1',defenderId:'p2',attendance:'full',phase:'melee',stage:'damage',currentAttackerId:'p1',damageRemaining:9,attackElements:['physical'],defenderMana:[]};s.phase='pvp-melee';s=reduceGame(s,{type:'PVP_FORCE_RETREAT',q:1,r:-1,playerId:'p1'});expect(s.phase).toBe('pvp-after');s=reduceGame(s,{type:'PVP_PLAY_AFTER',uid:heal.uid,mode:'basic',playerId:'p2'});expect(s.pvp.defenderHeal).toBe(2);s=reduceGame(s,{type:'PVP_SPEND_HEAL',playerId:'p2'});expect(s.players.find(player=>player.id==='p2').wounds).toBe(0);s=reduceGame(s,{type:'PVP_END_REACTION',playerId:'p2'});expect(s.phase).toBe('action');expect(s.pvp).toBeNull();expect(s.players.find(player=>player.id==='p2').discard.some(card=>card.uid===heal.uid)).toBe(true);});
  test('a fully attending PvP defender resolves an earned Skill before control returns',()=>{let s=started('full-conquest');const p2=s.players.find(player=>player.id==='p2');p2.fame=3;s.pvp={attackerId:'p1',defenderId:'p2',attendance:'full',phase:'melee',stage:'after',currentAttackerId:null,defenderHeal:0,defenderMana:[]};s.phase='pvp-after';s=reduceGame(s,{type:'PVP_END_REACTION',playerId:'p2'});expect(s.phase).toBe('level-up');expect(s.levelUpContext).toMatchObject({type:'pvp',playerId:'p2',aggressorId:'p1'});expect(s.pvp).not.toBeNull();const skill=s.skillChoices[0];s=reduceGame(s,{type:'SELECT_SKILL',id:skill.id,advancedId:s.offer.advanced[0].id,playerId:'p1'});expect(s.error).toMatch(/leveling player/i);expect(s.phase).toBe('level-up');s=reduceGame(s,{type:'SELECT_SKILL',id:skill.id,advancedId:s.offer.advanced[0].id,playerId:'p2'});expect(s.phase).toBe('action');expect(s.pvp).toBeNull();expect(s.player.id).toBe('p1');expect(s.players.find(player=>player.id==='p2').skills.some(item=>item.id===skill.id)).toBe(true);});
  test('PvP ranged Block cancels one Attack per two Block and attacker assigns full Armor costs',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);Object.assign(s.players.find(player=>player.id==='p1'),{q:0,r:0});Object.assign(s.players.find(player=>player.id==='p2'),{q:1,r:0});s.points.move=2;s.points.ranged=6;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});s=reduceGame(s,{type:'PVP_ATTEND',mode:'partial',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_USE_PREPARED',playerId:'p1'});s=reduceGame(s,{type:'PVP_DECLARE_ATTACK',playerId:'p1'});s.pvp.prepared.p2.block=4;s=reduceGame(s,{type:'PVP_USE_PREPARED',playerId:'p2'});s=reduceGame(s,{type:'PVP_RESOLVE_BLOCK',playerId:'p1'});expect(s.pvp.damageRemaining).toBe(4);s=reduceGame(s,{type:'PVP_DAMAGE_HERO',playerId:'p1'});expect(s.players.find(player=>player.id==='p2').wounds).toBe(1);expect(s.pvp.damageRemaining).toBe(2);s=reduceGame(s,{type:'PVP_FINISH_ATTACK',playerId:'p1'});expect(s.pvp.currentAttackerId).toBe('p2');});
