  test('a fully attending Arythea can use Motivation and Power of Pain during PvP',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),wound={id:'wound',uid:'pvp-pain',name:'Wound',color:'wound',basic:{},strong:{}};Object.assign(p1,{q:0,r:0});Object.assign(p2,{q:1,r:0,fame:-1,skills:[{...BASE_ARYTHEA_SKILLS.find(skill=>skill.id==='arythea-motivation'),used:false,roundUsed:false},{...BASE_ARYTHEA_SKILLS.find(skill=>skill.id==='power-of-pain'),used:false,roundUsed:false}],hand:[...p2.hand,wound],wounds:1});s.points.move=2;s.points.ranged=4;const before=p2.hand.length;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});s=reduceGame(s,{type:'PVP_ATTEND',mode:'full',playerId:'p2'});s=reduceGame(s,{type:'PVP_USE_SKILL',id:'arythea-motivation',playerId:'p2'});expect(s.players.find(player=>player.id==='p2').hand).toHaveLength(before+2);expect(s.pvp.defenderMana).toContain('red');s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_USE_PREPARED',playerId:'p1'});s=reduceGame(s,{type:'PVP_DECLARE_ATTACK',playerId:'p1'});s=reduceGame(s,{type:'PVP_USE_SKILL',id:'power-of-pain',mode:'block',woundUid:wound.uid,playerId:'p2'});expect(s.error).toBeNull();expect(s.pvp.blockPower).toBe(2);expect(s.players.find(player=>player.id==='p2').played.map(card=>card.uid)).toContain(wound.uid);});
