  test('an aggressor needs Siege Attack against a defender in a keep',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);const keep=s.map.find(hex=>hex.site==='keep'),p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),shot={id:'shot',uid:'shot-1',name:'Shot',color:'white',basic:{ranged:4},strong:{ranged:6}},flex={id:'flex-shot',uid:'flex-shot-1',name:'Flexible Shot',color:'red',basic:{anyCombat:4},strong:{anyCombat:6}};Object.assign(keep,{conquered:true,ownerId:'p2',enemy:null,enemies:[]});Object.assign(p1,{q:keep.q,r:keep.r,hand:[shot,flex]});Object.assign(p2,{q:keep.q,r:keep.r});s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});expect(s.phase).toBe('pvp-attend');s=reduceGame(s,{type:'PVP_ATTEND',mode:'partial',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_PLAY_CARD',uid:shot.uid,mode:'basic',playerId:'p1'});expect(s.error).toMatch(/no usable attack power/i);expect(s.pvp.attackPower).toBe(0);expect(s.players.find(player=>player.id==='p1').hand.some(card=>card.uid===shot.uid)).toBe(true);s=reduceGame(s,{type:'PVP_PLAY_CARD',uid:flex.uid,mode:'basic',effectAs:'siege',playerId:'p1'});expect(s.error).toBeNull();expect(s.pvp.attackPower).toBe(4);});
  test('Bow of Starsdawn basic discards selected non-Wounds for a PvP ranged attack',()=>{let s=started('full-conquest'),bow=artifactToHand(s,'bow-of-stars'),p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),fuel={id:'bow-fuel',uid:'bow-fuel',name:'Bow Fuel',color:'green',basic:{move:2}},wound={id:'wound',uid:'bow-pvp-wound',name:'Wound'};s.map.forEach(hex=>hex.revealed=true);Object.assign(p1,{q:0,r:0,hand:[bow,fuel,wound]});Object.assign(p2,{q:1,r:0});s.points.move=2;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});s=reduceGame(s,{type:'PVP_ATTEND',mode:'partial',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_PLAY_CARD',uid:bow.uid,mode:'basic',discardUids:[fuel.uid],playerId:'p1'});expect(s.error).toBeNull();expect(s.pvp.attackPower).toBe(2);expect(s.players.find(player=>player.id==='p1').discard.map(card=>card.uid)).toContain(fuel.uid);expect(s.players.find(player=>player.id==='p1').hand.map(card=>card.uid)).toContain(wound.uid);expect(s.players.find(player=>player.id==='p1').played.map(card=>card.id)).toContain('bow-of-stars');});
  test('Bow of Starsdawn strong resolves PvP card, Unit, and Skill contributions separately',()=>{let s=started('full-conquest'),bow=artifactToHand(s,'bow-of-stars'),p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2'),shot={id:'bow-pvp-shot',uid:'bow-pvp-shot',name:'PvP Shot',color:'white',basic:{fireRanged:3}},unit={...unitForTest('peasants','bow-pvp-unit'),powers:[{id:'bow-pvp-siege',effect:'iceSiege',value:4}]},skill={id:'bow-pvp-skill',name:'PvP Bow Skill',effect:'anyCombat',value:2,cadence:'turn',used:false,roundUsed:false};s.map.forEach(hex=>hex.revealed=true);Object.assign(p1,{q:0,r:0,hand:[bow,shot],units:[unit],skills:[skill]});Object.assign(p2,{q:1,r:0});s.points.move=2;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});s=reduceGame(s,{type:'PVP_ATTEND',mode:'partial',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_PLAY_CARD',uid:bow.uid,mode:'strong',playerId:'p1'});expect(s.pvp.bowTransformBy.p1).toBe(true);s=reduceGame(s,{type:'PVP_PLAY_CARD',uid:shot.uid,mode:'basic',playerId:'p1'});expect(s.pvp.pendingBowAttacks[0]).toMatchObject({actorId:'p1',stat:'fireRanged',amount:3});expect(s.pvp.attackPower).toBe(0);s=reduceGame(s,{type:'PVP_DECLARE_ATTACK',playerId:'p1'});expect(s.error).toMatch(/resolve the Bow/i);s=reduceGame(s,{type:'PVP_RESOLVE_BOW_ATTACK',mode:'double',playerId:'p1'});expect(s.pvp.attackPower).toBe(6);s=reduceGame(s,{type:'PVP_USE_UNIT',id:unit.uid,abilityId:'bow-pvp-siege',playerId:'p1'});s=reduceGame(s,{type:'PVP_RESOLVE_BOW_ATTACK',mode:'double-ranged',playerId:'p1'});expect(s.pvp.attackPower).toBe(14);s=reduceGame(s,{type:'PVP_USE_SKILL',id:skill.id,mode:'ranged',playerId:'p1'});s=reduceGame(s,{type:'PVP_RESOLVE_BOW_ATTACK',mode:'siege',playerId:'p1'});expect(s.error).toBeNull();expect(s.pvp.attackPower).toBe(16);expect(s.pvp.attackElements).toEqual(expect.arrayContaining(['fire','ice','physical']));expect(s.players.find(player=>player.id==='p1').removed.map(card=>card.id)).toContain('bow-of-stars');});
  test('Bow of Starsdawn can convert prepared Ranged power to Siege against a fortified PvP defender',()=>{let s=started('full-conquest'),bow=artifactToHand(s,'bow-of-stars'),keep=s.map.find(hex=>hex.site==='keep'),p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2');s.map.forEach(hex=>hex.revealed=true);Object.assign(keep,{conquered:true,ownerId:'p2',enemy:null,enemies:[]});Object.assign(p1,{q:keep.q,r:keep.r,hand:[bow]});Object.assign(p2,{q:keep.q,r:keep.r});s.points.fireRanged=3;s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});s=reduceGame(s,{type:'PVP_ATTEND',mode:'partial',playerId:'p2'});s=reduceGame(s,{type:'PVP_PASS',playerId:'p2'});s=reduceGame(s,{type:'PVP_PLAY_CARD',uid:bow.uid,mode:'strong',playerId:'p1'});s=reduceGame(s,{type:'PVP_USE_PREPARED',playerId:'p1'});expect(s.pvp.pendingBowAttacks[0]).toMatchObject({stat:'fireRanged',amount:3,siegeOnly:true});s=reduceGame(s,{type:'PVP_RESOLVE_BOW_ATTACK',mode:'double',playerId:'p1'});expect(s.error).toMatch(/only Siege Attack/i);expect(s.pvp.attackPower).toBe(0);s=reduceGame(s,{type:'PVP_RESOLVE_BOW_ATTACK',mode:'siege',playerId:'p1'});expect(s.error).toBeNull();expect(s.pvp.attackPower).toBe(3);expect(s.pvp.attackElements).toContain('fire');});
