  test('a fully attending PvP defender gets a separate Source die and mana view',()=>{let s=started('full-conquest');s.map.forEach(hex=>hex.revealed=true);const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2');Object.assign(p1,{q:0,r:0});Object.assign(p2,{q:1,r:0});s.points.move=2;s.mana=['red'];s=reduceGame(s,{type:'INITIATE_PVP',targetId:'p2',playerId:'p1'});s=reduceGame(s,{type:'PVP_ATTEND',mode:'full',playerId:'p2'});const die=s.source.find(item=>item.color!=='black'),color=die.color;s=reduceGame(s,{type:'PVP_TAKE_SOURCE',id:die.id,playerId:'p2'});expect(s.error).toBeNull();expect(s.pvp.defenderMana).toContain(color);expect(s.pvp.defenderSourceTaken).toBe(true);expect(gameViewForPlayer(s,'p2').mana).toContain(color);expect(gameViewForPlayer(s,'p2').sourceTaken).toBe(true);expect(gameViewForPlayer(s,'p1').mana).toEqual(['red']);s=reduceGame(s,{type:'PVP_TAKE_SOURCE',id:s.source[0].id,playerId:'p2'});expect(s.error).toMatch(/already used/i);});
