  test('a melee attacker may spend five damage to steal a public or wounded-Unit Artifact',()=>{let s=started('full-conquest'),p2=s.players.find(player=>player.id==='p2');p2.discard.push({id:'public-artifact',uid:'public-artifact-1',name:'Public Artifact',type:'artifact'});p2.hand.push({id:'hidden-artifact',uid:'hidden-artifact-1',name:'Hidden Artifact',type:'artifact'});p2.units=[{id:'wounded-unit',name:'Wounded Unit',wounded:true,banner:{id:'banner-captive',uid:'banner-captive-1',name:'Captive Banner',type:'artifact'}}];s.pvp={attackerId:'p1',defenderId:'p2',attendance:'partial',phase:'melee',stage:'damage',currentAttackerId:'p1',damageRemaining:15,attackElements:['physical']};s.phase='pvp-melee';s=reduceGame(s,{type:'PVP_STEAL_ARTIFACT',uid:'public-artifact-1',playerId:'p1'});expect(s.pvp.damageRemaining).toBe(10);expect(s.players.find(player=>player.id==='p1').discard.some(card=>card.uid==='public-artifact-1')).toBe(true);s=reduceGame(s,{type:'PVP_STEAL_ARTIFACT',uid:'banner-captive-1',playerId:'p1'});expect(s.pvp.damageRemaining).toBe(5);expect(s.players.find(player=>player.id==='p2').units[0].banner).toBeNull();expect(s.players.find(player=>player.id==='p1').discard.some(card=>card.uid==='banner-captive-1')).toBe(true);s=reduceGame(s,{type:'PVP_STEAL_ARTIFACT',uid:'hidden-artifact-1',playerId:'p1'});expect(s.error).toMatch(/discard pile, play area, or a Wounded Unit/i);expect(s.players.find(player=>player.id==='p2').hand.some(card=>card.uid==='hidden-artifact-1')).toBe(true);});
  test('PvP victory Fame always includes the base point when the winner has a lower level',()=>{let s=started('full-conquest');const p1=s.players.find(player=>player.id==='p1'),p2=s.players.find(player=>player.id==='p2');Object.assign(p1,{q:0,r:0,level:1,fame:20});Object.assign(p2,{q:0,r:0,level:3,fame:10});s.pvp={attackerId:'p1',defenderId:'p2',attendance:'partial',phase:'melee',stage:'damage',currentAttackerId:'p1',damageRemaining:9,attackElements:['physical']};s.phase='pvp-melee';s=reduceGame(s,{type:'PVP_FORCE_RETREAT',q:1,r:-1,playerId:'p1'});expect(s.error).toBeNull();expect(s.players.find(player=>player.id==='p1').fame).toBe(25);expect(s.players.find(player=>player.id==='p1').pvpWins).toBe(1);});
